import React, { useState, useEffect } from 'react';
import { useToast } from '../hooks/useToast';
import { motion } from 'framer-motion';
import { Plus, Folder, Trash2 } from 'lucide-react';
import { espacesTravailAPI } from '../services/api';
import GestionTaches from './GestionTaches';
import PartagesFichiers from './PartagesFichiers';

const EspacesTravail = ({ groupeId, isOwner }) => {
  const { showToast, ToastUI } = useToast();
  const [espaces, setEspaces] = useState([]);
  const [selectedEspace, setSelectedEspace] = useState(null);
  const [showCreate, setShowCreate] = useState(false);
  const [nom, setNom] = useState('');
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    chargerEspaces();
  }, [groupeId]);

  const chargerEspaces = async () => {
    if (!groupeId) {
      setEspaces([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const res = await espacesTravailAPI.listByGroupe(groupeId);
      setEspaces(res.data || []);
    } catch (err) {
      console.error('Erreur:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async () => {
    if (!nom.trim() || !groupeId) return;
    try {
      await espacesTravailAPI.create({
        groupeId,
        nom: nom.trim(),
        description: description.trim() || null,
        permission: 'PRIVATE',
      });
      setNom('');
      setDescription('');
      setShowCreate(false);
      chargerEspaces();
    } catch (err) {
      console.error('Erreur création:', err);
      showToast("Impossible de créer l'espace de travail.", 'error');
    }
  };

  const handleDelete = async (espaceId) => {
    if (!window.confirm('Supprimer cet espace?')) return;
    try {
      await espacesTravailAPI.delete(espaceId);
      if (selectedEspace?.id === espaceId) setSelectedEspace(null);
      chargerEspaces();
    } catch (err) {
      console.error('Erreur suppression:', err);
    }
  };

  if (selectedEspace) {
    return (
      <div className="space-y-4">
        <button
          onClick={() => setSelectedEspace(null)}
          className="text-blue-500 hover:text-blue-700 font-semibold"
        >
          ← Retour aux espaces
        </button>

        <div className="grid gap-4 lg:grid-cols-2">
          <GestionTaches espaceTravailId={selectedEspace.id} />
          <PartagesFichiers espaceTravailId={selectedEspace.id} />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {ToastUI}
      {/* Header */}
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">📁 Espaces de travail</h2>
        {isOwner && (
          <button
            onClick={() => setShowCreate(true)}
            className="bg-blue-500 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-600"
          >
            <Plus size={20} />
            Créer
          </button>
        )}
      </div>

      {/* Create Modal */}
      {showCreate && (
        <motion.div className="bg-gradient-to-br from-blue-50 to-purple-50 p-4 rounded-lg border border-blue-200">
          <input
            type="text"
            value={nom}
            onChange={(e) => setNom(e.target.value)}
            placeholder="Nom de l'espace..."
            className="w-full px-4 py-2 border rounded-lg mb-3 focus:outline-none focus:border-blue-500"
          />
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Description (optionnel)..."
            className="w-full px-4 py-2 border rounded-lg mb-3 focus:outline-none focus:border-blue-500"
            rows="2"
          />
          <div className="flex gap-2">
            <button
              onClick={handleCreate}
              className="flex-1 bg-blue-500 text-white py-2 rounded-lg hover:bg-blue-600 font-semibold"
            >
              ✨ Créer
            </button>
            <button
              onClick={() => setShowCreate(false)}
              className="flex-1 bg-gray-300 text-gray-800 py-2 rounded-lg hover:bg-gray-400"
            >
              Annuler
            </button>
          </div>
        </motion.div>
      )}

      {/* Loading */}
      {loading && <div className="text-center py-8">⏳ Chargement...</div>}

      {/* Empty State */}
      {!loading && espaces.length === 0 && (
        <div className="text-center py-12 bg-gray-50 rounded-lg">
          <Folder size={48} className="mx-auto text-gray-400 mb-4" />
          <p className="text-gray-600">Aucun espace de travail créé</p>
          {isOwner && (
            <button
              onClick={() => setShowCreate(true)}
              className="mt-4 text-blue-500 hover:text-blue-700 font-semibold"
            >
              + Créer un espace
            </button>
          )}
        </div>
      )}

      {/* Espaces List */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {espaces.map(espace => (
          <motion.div
            key={espace.id}
            whileHover={{ translateY: -4 }}
            className="bg-gradient-to-br from-blue-50 to-purple-50 p-4 rounded-lg border border-blue-200 cursor-pointer hover:shadow-lg transition"
            onClick={() => setSelectedEspace(espace)}
          >
            <div className="flex justify-between items-start">
              <div className="flex-1">
                <h3 className="font-semibold text-lg">{espace.nom}</h3>
                {espace.description && (
                  <p className="text-sm text-gray-600 mt-1">{espace.description}</p>
                )}
              </div>
              {isOwner && (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDelete(espace.id);
                  }}
                  className="p-2 hover:bg-red-100 rounded-lg text-red-500"
                >
                  <Trash2 size={18} />
                </button>
              )}
            </div>
            <div className="mt-4 pt-4 border-t text-xs text-gray-600">
              {espace.permission === 'PUBLIC' ? '🌍 Public' : '🔒 Privé'}
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default EspacesTravail;
