import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Plus, CheckCircle2, Circle, Trash2 } from 'lucide-react';
import { tachesAPI } from '../services/api';

const GestionTaches = ({ espaceTravailId }) => {
  const [taches, setTaches] = useState([]);
  const [showCreate, setShowCreate] = useState(false);
  const [titre, setTitre] = useState('');
  const [description, setDescription] = useState('');
  const [priorite, setPriorite] = useState('NORMAL');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    chargerTaches();
  }, [espaceTravailId]);

  const chargerTaches = async () => {
    if (!espaceTravailId) {
      setTaches([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const res = await tachesAPI.listByEspace(espaceTravailId);
      setTaches(res.data || []);
    } catch (err) {
      console.error('Erreur:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async () => {
    if (!titre.trim() || !espaceTravailId) return;
    try {
      await tachesAPI.create({
        espaceTravailId,
        titre: titre.trim(),
        description: description.trim() || null,
        priorite,
      });
      setTitre('');
      setDescription('');
      setPriorite('NORMAL');
      setShowCreate(false);
      chargerTaches();
    } catch (err) {
      console.error('Erreur création:', err);
    }
  };

  const handleToggle = async (tacheId, currentStatus) => {
    const nextStatus = currentStatus === 'TERMINEE' ? 'A_FAIRE' : 'TERMINEE';
    try {
      await tachesAPI.update(tacheId, { statut: nextStatus });
      chargerTaches();
    } catch (err) {
      console.error('Erreur update:', err);
    }
  };

  const handleDelete = async (tacheId) => {
    if (!window.confirm('Supprimer cette tâche?')) return;
    try {
      await tachesAPI.delete(tacheId);
      chargerTaches();
    } catch (err) {
      console.error('Erreur suppression:', err);
    }
  };

  const getPrioriteColor = (priorite) => {
    switch (priorite) {
      case 'URGENTE': return 'bg-red-100 text-red-700';
      case 'HAUTE': return 'bg-orange-100 text-orange-700';
      case 'NORMAL': return 'bg-blue-100 text-blue-700';
      case 'BASSE': return 'bg-green-100 text-green-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex justify-between items-center">
        <h3 className="text-xl font-bold">📌 Tâches</h3>
        <button
          onClick={() => setShowCreate(true)}
          className="bg-blue-500 text-white px-3 py-2 rounded-lg flex items-center gap-1 hover:bg-blue-600 text-sm"
        >
          <Plus size={16} />
          Ajouter
        </button>
      </div>

      {/* Create Modal */}
      {showCreate && (
        <motion.div className="bg-gradient-to-br from-blue-50 to-purple-50 p-4 rounded-lg border border-blue-200 space-y-3">
          <input
            type="text"
            value={titre}
            onChange={(e) => setTitre(e.target.value)}
            placeholder="Titre de la tâche..."
            className="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none focus:border-blue-500"
          />
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Description..."
            className="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none focus:border-blue-500"
            rows="2"
          />
          <select
            value={priorite}
            onChange={(e) => setPriorite(e.target.value)}
            className="w-full px-3 py-2 border rounded-lg text-sm"
          >
            <option value="BASSE">🟢 Basse</option>
            <option value="NORMAL">🔵 Normal</option>
            <option value="HAUTE">🟠 Haute</option>
            <option value="URGENTE">🔴 Urgente</option>
          </select>
          <div className="flex gap-2">
            <button
              onClick={handleCreate}
              className="flex-1 bg-blue-500 text-white py-2 rounded-lg hover:bg-blue-600 text-sm font-semibold"
            >
              ✨ Créer
            </button>
            <button
              onClick={() => setShowCreate(false)}
              className="flex-1 bg-gray-300 text-gray-800 py-2 rounded-lg hover:bg-gray-400 text-sm"
            >
              Annuler
            </button>
          </div>
        </motion.div>
      )}

      {/* Loading */}
      {loading && <div className="text-center py-6 text-gray-500">⏳ Chargement...</div>}

      {/* Empty State */}
      {!loading && taches.length === 0 && (
        <div className="text-center py-8 bg-gray-50 rounded-lg">
          <p className="text-gray-600">Aucune tâche pour le moment</p>
        </div>
      )}

      {/* Tâches List */}
      <div className="space-y-2">
        {taches.map(tache => (
          <motion.div
            key={tache.id}
            initial={{ x: -10, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            className={`p-3 rounded-lg border-2 transition ${
              tache.statut === 'TERMINEE'
                ? 'bg-gray-50 border-gray-200 opacity-60'
                : 'bg-white border-blue-200 hover:border-blue-400'
            }`}
          >
            <div className="flex items-start gap-3">
              <button
                onClick={() => handleToggle(tache.id, tache.statut)}
                className="mt-1 text-blue-500 hover:text-blue-700"
              >
                {tache.statut === 'TERMINEE' ? (
                  <CheckCircle2 size={20} />
                ) : (
                  <Circle size={20} />
                )}
              </button>

              <div className="flex-1 min-w-0">
                <h4 className={`font-semibold text-sm ${
                  tache.statut === 'TERMINEE' ? 'line-through text-gray-500' : 'text-gray-800'
                }`}>
                  {tache.titre}
                </h4>
                {tache.description && (
                  <p className="text-xs text-gray-600 mt-1">{tache.description}</p>
                )}
                <div className="flex items-center gap-2 mt-2">
                  <span className={`text-xs px-2 py-1 rounded ${getPrioriteColor(tache.priorite)}`}>
                    {tache.priorite}
                  </span>
                  {tache.progression !== undefined && (
                    <div className="w-20 h-1 bg-gray-200 rounded-full overflow-hidden">
                      <div
                        className="h-full bg-blue-500"
                        style={{ width: `${tache.progression}%` }}
                      />
                    </div>
                  )}
                </div>
              </div>

              <button
                onClick={() => handleDelete(tache.id)}
                className="p-1 hover:bg-red-100 rounded text-red-500"
              >
                <Trash2 size={16} />
              </button>
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default GestionTaches;
