import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { Plus, Download, Trash2, FileText, Image as ImageIcon, File } from 'lucide-react';
import { fichiersPartagesAPI, BACKEND_BASE_URL } from '../services/api';

const PartagesFichiers = ({ espaceTravailId }) => {
  const [fichiers, setFichiers] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [uploadError, setUploadError] = useState('');
  const fileInputRef = useRef(null);

  useEffect(() => {
    chargerFichiers();
  }, [espaceTravailId]);

  const chargerFichiers = async () => {
    if (!espaceTravailId) {
      setFichiers([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const res = await fichiersPartagesAPI.listByEspace(espaceTravailId);
      setFichiers(res.data || []);
    } catch (err) {
      console.error('Erreur:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file || !espaceTravailId) return;

    setUploading(true);
    setUploadError('');
    try {
      const formData = new FormData();
      formData.append('file', file);
      await fichiersPartagesAPI.upload(espaceTravailId, formData);
      chargerFichiers();
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (err) {
      console.error('Erreur upload:', err);
      const status = err?.response?.status;
      if (status === 413) setUploadError('❌ Fichier trop volumineux (max 50 Mo).');
      else if (status === 401 || status === 403) setUploadError('❌ Session expirée. Reconnectez-vous.');
      else setUploadError('❌ Upload échoué. Vérifiez votre connexion et réessayez.');
      setTimeout(() => setUploadError(''), 4000);
    } finally {
      setUploading(false);
    }
  };

  const handleDelete = async (fichierId) => {
    if (!window.confirm('Supprimer ce fichier?')) return;
    try {
      await fichiersPartagesAPI.delete(fichierId);
      chargerFichiers();
    } catch (err) {
      console.error('Erreur suppression:', err);
    }
  };

  const resolveFileUrl = (url) => {
    if (!url) return '';
    if (url.startsWith('http')) return url;
    return `${BACKEND_BASE_URL}${url.startsWith('/') ? url : `/${url}`}`;
  };

  const handleDownload = (fichier) => {
    if (fichier.urlFichier) {
      const link = document.createElement('a');
      link.href = resolveFileUrl(fichier.urlFichier);
      link.download = fichier.nomFichier || fichier.nom;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.click();
    }
  };

  const getFileIcon = (typeFichier) => {
    if (typeFichier?.includes('image')) return <ImageIcon size={24} className="text-blue-500" />;
    if (typeFichier?.includes('pdf')) return <FileText size={24} className="text-red-500" />;
    return <File size={24} className="text-gray-500" />;
  };

  const formatFileSize = (bytes) => {
    if (!bytes) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
  };

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex justify-between items-center">
        <h3 className="text-xl font-bold">📁 Fichiers partagés</h3>
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={uploading}
          className="bg-blue-500 text-white px-3 py-2 rounded-lg flex items-center gap-1 hover:bg-blue-600 text-sm disabled:opacity-50"
        >
          <Plus size={16} />
          Upload
        </button>
        <input
          ref={fileInputRef}
          type="file"
          onChange={handleUpload}
          className="hidden"
        />
      </div>

      {/* Erreur upload */}
      {uploadError && (
        <div style={{ background: '#fee2e2', color: '#dc2626', padding: '10px 14px', borderRadius: '8px', fontSize: '0.88rem', fontWeight: 600 }}>
          {uploadError}
        </div>
      )}

      {/* Loading */}
      {loading && <div className="text-center py-6 text-gray-500">⏳ Chargement...</div>}

      {/* Empty State */}
      {!loading && fichiers.length === 0 && (
        <div className="text-center py-8 bg-gray-50 rounded-lg">
          <p className="text-gray-600">Aucun fichier partagé</p>
          <button
            onClick={() => fileInputRef.current?.click()}
            className="mt-3 text-blue-500 hover:text-blue-700 font-semibold text-sm"
          >
            + Ajouter un fichier
          </button>
        </div>
      )}

      {/* Uploading */}
      {uploading && (
        <motion.div
          initial={{ y: -10, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="bg-blue-50 p-4 rounded-lg border border-blue-200"
        >
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 bg-blue-500 rounded-full animate-spin" />
            <span className="text-sm font-semibold">⏳ Upload en cours...</span>
          </div>
        </motion.div>
      )}

      {/* Fichiers List */}
      <div className="space-y-2">
        {fichiers.map(fichier => (
          <motion.div
            key={fichier.id}
            initial={{ x: -10, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            className="bg-white p-3 rounded-lg border-2 border-gray-200 hover:border-blue-300 transition"
          >
            <div className="flex items-start gap-3">
              {/* Icon */}
              <div className="mt-1">
                {getFileIcon(fichier.typeFichier)}
              </div>

              {/* Info */}
              <div className="flex-1 min-w-0">
                <h4 className="font-semibold text-sm text-gray-800 truncate">
                  {fichier.nom || fichier.nomFichier}
                </h4>
                {fichier.description && (
                  <p className="text-xs text-gray-600 mt-1">{fichier.description}</p>
                )}
                <div className="flex items-center gap-2 mt-2 text-xs text-gray-500">
                  <span>{formatFileSize(fichier.tailleOctets)}</span>
                  <span>•</span>
                  <span>{fichier.uploader?.nomComplet}</span>
                </div>
              </div>

              {/* Actions */}
              <div className="flex gap-1">
                <button
                  onClick={() => handleDownload(fichier)}
                  className="p-2 hover:bg-blue-100 rounded text-blue-500"
                  title="Télécharger"
                >
                  <Download size={16} />
                </button>
                <button
                  onClick={() => handleDelete(fichier.id)}
                  className="p-2 hover:bg-red-100 rounded text-red-500"
                  title="Supprimer"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default PartagesFichiers;
