import React, { useState, useEffect, useRef } from 'react';
import { useToast } from '../hooks/useToast';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search, Send, Paperclip, MoreVertical,
  Users, Hash, MessageSquare, ArrowLeft,
  Image as ImageIcon, Mic, MicOff, Plus, X, FileText, Loader2, UserPlus, FolderOpen
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { messagingAPI, fileAPI, BACKEND_BASE_URL } from '../services/api';
import { pushBackHandler, getDashboardPathForRole } from '../utils/backHandler';
import { getStoredSession } from '../utils/authSession';
import EspacesTravail from './EspacesTravail';
import './Messaging.css';

const Messaging = () => {
  const navigate = useNavigate();
  const { showToast, ToastUI } = useToast();
  const [groups, setGroups] = useState([]);
  const [activeGroupId, setActiveGroupId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [showCreateGroup, setShowCreateGroup] = useState(false);
  const [newGroupName, setNewGroupName] = useState('');
  const [newGroupType, setNewGroupType] = useState('PUBLIC');
  const [attachment, setAttachment] = useState(null);
  const [attachmentPreview, setAttachmentPreview] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [joiningGroupId, setJoiningGroupId] = useState(null);
  const [panelMode, setPanelMode] = useState('chat');

  // Voice recording
  const [isRecording, setIsRecording] = useState(false);
  const [recordingSeconds, setRecordingSeconds] = useState(0);
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);
  const recordingTimerRef = useRef(null);

  const fileInputRef = useRef(null);
  const messagesEndRef = useRef(null);
  const myPhone = localStorage.getItem('phone') || '';

  useEffect(() => {
    loadGroups();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (activeGroupId) loadMessages(activeGroupId);
  }, [activeGroupId]);

  useEffect(() => {
    if (activeGroupId) setPanelMode('chat');
  }, [activeGroupId]);

  const handleNavigateBack = () => {
    if (showCreateGroup) { setShowCreateGroup(false); return; }
    if (panelMode === 'workspaces') { setPanelMode('chat'); return; }
    if (activeGroupId) { setActiveGroupId(null); return; }
    const { role } = getStoredSession();
    navigate(getDashboardPathForRole(role), { replace: true });
  };

  // Bouton RETOUR Android
  useEffect(() => {
    const off = pushBackHandler(() => {
      if (showCreateGroup) { setShowCreateGroup(false); return true; }
      if (panelMode === 'workspaces') { setPanelMode('chat'); return true; }
      if (activeGroupId) { setActiveGroupId(null); return true; }
      handleNavigateBack();
      return true;
    });
    return off;
  }, [showCreateGroup, panelMode, activeGroupId, navigate]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Auto-refresh messages every 5s
  useEffect(() => {
    if (!activeGroupId) return;
    const interval = setInterval(() => loadMessages(activeGroupId), 5000);
    return () => clearInterval(interval);
  }, [activeGroupId]);

  // Cleanup recording timer on unmount
  useEffect(() => {
    return () => {
      if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
    };
  }, []);

  const loadGroups = async () => {
    try {
      const res = await messagingAPI.getGroupes();
      setGroups(res.data);
      if (res.data.length > 0 && !activeGroupId) {
        setActiveGroupId(res.data[0].id);
      }
    } catch (err) {
      console.error('Erreur chargement groupes', err);
    } finally {
      setLoading(false);
    }
  };

  const loadMessages = async (groupeId) => {
    try {
      const res = await messagingAPI.getMessages(groupeId);
      setMessages(res.data);
    } catch (err) {
      console.error('Erreur chargement messages', err);
      setMessages([]);
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setAttachment(file);
    if (file.type.startsWith('image/')) {
      setAttachmentPreview({ type: 'image', url: URL.createObjectURL(file) });
    } else {
      setAttachmentPreview({ type: 'document', name: file.name });
    }
  };

  const removeAttachment = () => {
    setAttachment(null);
    if (attachmentPreview?.url) URL.revokeObjectURL(attachmentPreview.url);
    setAttachmentPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    if ((!message.trim() && !attachment) || !activeGroupId || uploading) return;
    try {
      let pieceJointeUrl = null;
      let typeMessage = 'TEXTE';
      if (attachment) {
        setUploading(true);
        const fd = new FormData();
        fd.append('file', attachment);
        const uploadRes = await fileAPI.uploadFile(fd);
        pieceJointeUrl = uploadRes.data.url;
        typeMessage = attachment.type.startsWith('image/') ? 'IMAGE' : 'DOCUMENT';
      }
      await messagingAPI.sendMessage(activeGroupId, message, typeMessage, pieceJointeUrl);
      setMessage('');
      removeAttachment();
      loadMessages(activeGroupId);
    } catch (err) {
      const errMsg = err.response?.data?.message || err.response?.data?.error;
      if (err.response?.data?.error === 'GROUPE_NON_REJOINT') {
        showToast("Vous devez rejoindre ce groupe avant d'envoyer un message.", 'warning');
      } else if (err.response?.data?.error === 'CONTENU_REFUSE') {
        showToast('⚠️ Votre message a été bloqué par la modération. Veuillez revoir son contenu.', 'warning');
      } else {
        showToast("Erreur lors de l'envoi. Veuillez réessayer.", 'error');
      }
      console.error('Erreur envoi', err);
    } finally {
      setUploading(false);
    }
  };

  // ── Voice Recording ─────────────────────────────────────────────────────────

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mimeType = MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm' : 'audio/ogg';
      const recorder = new MediaRecorder(stream, { mimeType });
      audioChunksRef.current = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };
      recorder.onstop = () => {
        stream.getTracks().forEach(t => t.stop());
        sendVoiceMessage(mimeType);
      };
      recorder.start(100); // collect data every 100ms
      mediaRecorderRef.current = recorder;
      setIsRecording(true);
      setRecordingSeconds(0);
      recordingTimerRef.current = setInterval(() => setRecordingSeconds(s => s + 1), 1000);
    } catch (err) {
      showToast("Impossible d'accéder au microphone. Vérifiez les permissions du navigateur.", 'error');
      console.error('Mic error', err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    if (recordingTimerRef.current) {
      clearInterval(recordingTimerRef.current);
      recordingTimerRef.current = null;
    }
    setIsRecording(false);
    setRecordingSeconds(0);
  };

  const handleMicClick = () => {
    if (isRecording) {
      stopRecording();
    } else {
      startRecording();
    }
  };

  const sendVoiceMessage = async (mimeType) => {
    if (audioChunksRef.current.length === 0 || !activeGroupId) return;
    try {
      setUploading(true);
      const audioBlob = new Blob(audioChunksRef.current, { type: mimeType });
      const ext = mimeType.includes('webm') ? 'webm' : 'ogg';
      const audioFile = new File([audioBlob], `voice-message.${ext}`, { type: mimeType });
      const fd = new FormData();
      fd.append('file', audioFile);
      const uploadRes = await fileAPI.uploadFile(fd);
      await messagingAPI.sendMessage(activeGroupId, '🎙️ Message vocal', 'AUDIO', uploadRes.data.url);
      loadMessages(activeGroupId);
    } catch (err) {
      console.error('Erreur envoi audio', err);
      showToast("Erreur lors de l'envoi du message vocal.", 'error');
    } finally {
      setUploading(false);
      audioChunksRef.current = [];
    }
  };

  // ── Rejoindre un groupe ──────────────────────────────────────────────────────

  const handleJoinGroup = async (groupId, e) => {
    e.stopPropagation();
    setJoiningGroupId(groupId);
    try {
      await messagingAPI.joinGroupe(groupId);
      loadGroups();
    } catch (err) {
      console.error('Erreur rejoindre groupe', err);
    } finally {
      setJoiningGroupId(null);
    }
  };

  const isMember = (group) => {
    if (!group.membres || group.membres.length === 0) return true; // assume member if no list
    return group.membres.some(m => m.numeroTelephone === myPhone);
  };

  // ── Groupes filtrés ──────────────────────────────────────────────────────────

  const filteredGroups = groups.filter(g =>
    !searchQuery || g.nom?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleCreateGroup = async (e) => {
    e.preventDefault();
    try {
      const res = await messagingAPI.createGroupe({ nom: newGroupName, typeGroupe: newGroupType });
      setNewGroupName('');
      setShowCreateGroup(false);
      await loadGroups();
      setActiveGroupId(res.data.id);
    } catch (err) {
      showToast('Erreur création du groupe', 'error');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const formatDuration = (s) => `${Math.floor(s / 60).toString().padStart(2,'0')}:${(s % 60).toString().padStart(2,'0')}`;

  const activeGroup = groups.find(g => g.id === activeGroupId);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      style={{ position: 'relative' }}>
      {ToastUI}
      <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="messaging-layout"
    >
      {/* ── Sidebar groupes ── */}
      <aside className="msg-sidebar">
        <div className="msg-sidebar-header">
          <button onClick={handleNavigateBack} className="btn-icon" title="Retour"><ArrowLeft size={20} /></button>
          <h2 style={{ flex: 1 }}>Discussions</h2>
          <button onClick={() => setShowCreateGroup(true)} className="btn-icon" title="Créer un groupe">
            <Plus size={20} />
          </button>
        </div>

        <div className="msg-search">
          <Search size={18} />
          <input
            type="text"
            placeholder="Rechercher un groupe..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
          />
        </div>

        <div className="groups-list">
          {loading ? (
            <p style={{ textAlign: 'center', color: '#475569', padding: '2rem' }}>Chargement...</p>
          ) : filteredGroups.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '2rem', color: '#475569' }}>
              <Users size={40} style={{ margin: '0 auto 10px', opacity: 0.5 }} />
              <p>Aucun groupe disponible</p>
              <button onClick={() => setShowCreateGroup(true)} className="btn-primary"
                style={{ marginTop: '1rem', padding: '8px 16px', fontSize: '0.85rem' }}>
                Créer un groupe
              </button>
            </div>
          ) : filteredGroups.map((group) => (
            <div
              key={group.id}
              onClick={() => setActiveGroupId(group.id)}
              className={`group-item ${activeGroupId === group.id ? 'active' : ''}`}
            >
              <div className="group-avatar">
                {group.typeGroupe === 'PUBLIC' ? <Hash size={20} /> : <Users size={20} />}
              </div>
              <div className="group-info">
                <div className="group-name-row">
                  <span className="group-name">{group.nom}</span>
                  <span className="group-time" style={{
                    fontSize: '0.65rem',
                    background: group.typeGroupe === 'PUBLIC' ? '#DBEAFE' : '#FEF9C3',
                    padding: '2px 8px',
                    borderRadius: '50px',
                    color: group.typeGroupe === 'PUBLIC' ? '#1D4ED8' : '#92400E',
                    fontWeight: 700,
                  }}>{group.typeGroupe}</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <p className="group-last-msg">
                    {group.createur?.nomComplet ? `Créé par ${group.createur.nomComplet}` : ''}
                  </p>
                  {!isMember(group) && (
                    <button
                      onClick={(e) => handleJoinGroup(group.id, e)}
                      disabled={joiningGroupId === group.id}
                      title="Rejoindre"
                      style={{
                        background: '#1D4ED8', color: 'white', border: 'none',
                        borderRadius: '8px', padding: '3px 8px', fontSize: '0.7rem',
                        cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px',
                        fontWeight: 700,
                      }}
                    >
                      <UserPlus size={11} />
                      {joiningGroupId === group.id ? '...' : 'Rejoindre'}
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </aside>

      {/* ── Zone de Chat ── */}
      <main className="chat-area">
        {activeGroup ? (
          <>
            <header className="chat-header">
              <div className="chat-header-info">
                <h3 className="chat-title">{activeGroup.nom}</h3>
                <span className="chat-subtitle">
                  {activeGroup.typeGroupe === 'PUBLIC' ? 'Groupe public' : 'Groupe privé'}
                  {activeGroup.membres && ` · ${activeGroup.membres.length} membre(s)`}
                </span>
              </div>
              <div className="chat-header-actions" style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                <button
                  type="button"
                  className="btn-icon"
                  title="Messages"
                  onClick={() => setPanelMode('chat')}
                  style={{ background: panelMode === 'chat' ? '#DBEAFE' : undefined }}
                >
                  <MessageSquare size={20} />
                </button>
                <button
                  type="button"
                  className="btn-icon"
                  title="Espaces de travail"
                  onClick={() => setPanelMode('workspaces')}
                  style={{ background: panelMode === 'workspaces' ? '#DBEAFE' : undefined }}
                >
                  <FolderOpen size={20} />
                </button>
                <button type="button" className="btn-icon"><Search size={20} /></button>
                <button type="button" className="btn-icon"><MoreVertical size={20} /></button>
              </div>
            </header>

            {panelMode === 'workspaces' ? (
              <div style={{ flex: 1, overflow: 'auto', padding: '1.5rem', background: '#F8FAFC' }}>
                <EspacesTravail
                  groupeId={activeGroupId}
                  isOwner={activeGroup.createur?.numeroTelephone === myPhone}
                />
              </div>
            ) : (
            <>
            <div className="messages-container">
              {messages.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '3rem', color: '#475569' }}>
                  <MessageSquare size={50} style={{ opacity: 0.3, margin: '0 auto 15px' }} />
                  <p>Aucun message dans ce groupe. Soyez le premier à écrire !</p>
                </div>
              ) : messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`message-wrapper ${msg.expediteur?.numeroTelephone === myPhone ? 'me' : 'other'}`}
                >
                  <span className="msg-user">{msg.expediteur?.nomComplet || 'Utilisateur'}</span>
                  <div
                    className={`message-bubble ${msg.isFlagged ? 'flagged' : ''}`}
                    style={msg.isFlagged ? { border: '2px solid #E11D48', opacity: 0.7 } : {}}
                  >
                    {msg.isFlagged && (
                      <span style={{ fontSize: '0.7rem', color: '#E11D48', fontWeight: '800', display: 'block', marginBottom: 4 }}>
                        ⚠ Message signalé par l'IA
                      </span>
                    )}
                    {/* Image */}
                    {msg.pieceJointeUrl && msg.typeMessage === 'IMAGE' && (
                      <div style={{ marginBottom: '8px' }}>
                        <img
                          src={msg.pieceJointeUrl?.startsWith('http') ? msg.pieceJointeUrl : `${BACKEND_BASE_URL}${msg.pieceJointeUrl?.startsWith('/') ? msg.pieceJointeUrl : '/' + msg.pieceJointeUrl}`}
                          alt="Attachment"
                          style={{ maxWidth: '100%', borderRadius: '8px', maxHeight: '200px', objectFit: 'cover' }}
                        />
                      </div>
                    )}
                    {/* Document */}
                    {msg.pieceJointeUrl && msg.typeMessage === 'DOCUMENT' && (
                      <div style={{ marginBottom: '8px', display: 'flex', alignItems: 'center', gap: '8px', background: 'rgba(255,255,255,0.2)', padding: '8px', borderRadius: '8px' }}>
                        <FileText size={20} />
                        <a
                          href={msg.pieceJointeUrl?.startsWith('http') ? msg.pieceJointeUrl : `${BACKEND_BASE_URL}${msg.pieceJointeUrl?.startsWith('/') ? msg.pieceJointeUrl : '/' + msg.pieceJointeUrl}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          style={{ color: 'inherit', textDecoration: 'underline', fontSize: '0.9rem' }}
                        >
                          Ouvrir le document
                        </a>
                      </div>
                    )}
                    {/* Audio */}
                    {msg.pieceJointeUrl && msg.typeMessage === 'AUDIO' && (
                      <div style={{ marginBottom: '6px' }}>
                        <audio
                          controls
                          src={msg.pieceJointeUrl?.startsWith('http') ? msg.pieceJointeUrl : `${BACKEND_BASE_URL}${msg.pieceJointeUrl?.startsWith('/') ? msg.pieceJointeUrl : '/' + msg.pieceJointeUrl}`}
                          style={{ width: '100%', minWidth: '200px', height: '36px', borderRadius: '8px' }}
                        />
                      </div>
                    )}
                    {/* Texte */}
                    {msg.contenu && msg.typeMessage !== 'AUDIO' && <span>{msg.contenu}</span>}
                    <span className="msg-time">
                      {msg.dateEnvoi
                        ? new Date(msg.dateEnvoi).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                        : ''}
                    </span>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            {/* ── Zone de saisie ── */}
            <footer className="chat-input-area" style={{ flexDirection: 'column', alignItems: 'stretch' }}>
              {/* Preview pièce jointe */}
              {attachmentPreview && (
                <div style={{ padding: '8px 12px', background: '#0f172a', borderRadius: '12px 12px 0 0', display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 4 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    {attachmentPreview.type === 'image' ? (
                      <img src={attachmentPreview.url} alt="Preview" style={{ width: '40px', height: '40px', objectFit: 'cover', borderRadius: '6px' }} />
                    ) : (
                      <div style={{ width: '40px', height: '40px', background: '#E2E8F0', borderRadius: '6px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <FileText size={20} />
                      </div>
                    )}
                    <span style={{ fontSize: '0.85rem', color: '#475569', maxWidth: '200px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {attachmentPreview.type === 'image' ? 'Image sélectionnée' : attachmentPreview.name}
                    </span>
                  </div>
                  <button onClick={removeAttachment} className="btn-icon" style={{ padding: '4px' }}>
                    <X size={16} />
                  </button>
                </div>
              )}

              {/* Indicateur d'enregistrement */}
              {isRecording && (
                <div style={{
                  display: 'flex', alignItems: 'center', gap: '12px', padding: '8px 16px',
                  background: '#FEF2F2', borderRadius: '12px', marginBottom: 8,
                  border: '1px solid #FECACA',
                }}>
                  <div style={{
                    width: 10, height: 10, borderRadius: '50%', background: '#E11D48',
                    animation: 'pulse 1s infinite',
                  }} />
                  <span style={{ fontWeight: 700, color: '#E11D48', fontSize: '0.9rem' }}>
                    🎙️ Enregistrement... {formatDuration(recordingSeconds)}
                  </span>
                  <span style={{ fontSize: '0.8rem', color: '#475569', marginLeft: 'auto' }}>
                    Cliquez sur 🛑 pour envoyer
                  </span>
                </div>
              )}

              <div style={{ display: 'flex', alignItems: 'center', gap: '10px', width: '100%' }}>
                <div className="input-toolbar">
                  <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    style={{ display: 'none' }}
                    accept=".pdf,.doc,.docx,.png,.jpg,.jpeg"
                  />
                  <button className="btn-icon-light" onClick={() => fileInputRef.current?.click()} title="Joindre un fichier">
                    <Paperclip size={20} />
                  </button>
                  <button
                    className="btn-icon-light"
                    onClick={handleMicClick}
                    title={isRecording ? 'Arrêter l\'enregistrement' : 'Message vocal'}
                    style={isRecording ? { color: '#E11D48', background: '#FEF2F2', borderRadius: '10px' } : {}}
                  >
                    {isRecording ? <MicOff size={20} /> : <Mic size={20} />}
                  </button>
                </div>

                <div className="main-input">
                  <input
                    type="text"
                    placeholder={
                      isRecording ? '🎙️ Enregistrement vocal en cours...'
                        : uploading ? 'Envoi en cours...'
                        : 'Écrivez votre message...'
                    }
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    onKeyDown={handleKeyPress}
                    disabled={uploading || isRecording}
                  />
                </div>

                <button className="btn-send" onClick={handleSend} disabled={uploading || isRecording}>
                  {uploading
                    ? <Loader2 size={20} style={{ animation: 'spin 1s linear infinite' }} />
                    : <Send size={20} />
                  }
                </button>
              </div>
            </footer>
            </>
            )}
          </>
        ) : (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: '#475569' }}>
            <div style={{ textAlign: 'center' }}>
              <MessageSquare size={60} style={{ opacity: 0.3, margin: '0 auto 15px' }} />
              <h3>Sélectionnez une discussion</h3>
              <p>ou créez un nouveau groupe pour commencer</p>
            </div>
          </div>
        )}
      </main>

      {/* ── Modal Création Groupe ── */}
      <AnimatePresence>
        {showCreateGroup && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, backdropFilter: 'blur(5px)' }}
            onClick={(e) => { if (e.target === e.currentTarget) setShowCreateGroup(false); }}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              style={{ background: 'white', padding: '2.5rem', borderRadius: '30px', width: '450px', boxShadow: '0 25px 60px rgba(0,0,0,0.15)' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
                <h3 style={{ fontWeight: '800', fontSize: '1.2rem' }}>Nouveau Groupe</h3>
                <button onClick={() => setShowCreateGroup(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>
                  <X size={20} />
                </button>
              </div>
              <form onSubmit={handleCreateGroup} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                <input
                  type="text"
                  placeholder="Nom du groupe"
                  value={newGroupName}
                  onChange={e => setNewGroupName(e.target.value)}
                  required
                  style={{ padding: '12px', borderRadius: '12px', border: '1.5px solid #E2E8F0', fontFamily: 'inherit', fontSize: '0.95rem', outline: 'none' }}
                />
                <select
                  value={newGroupType}
                  onChange={e => setNewGroupType(e.target.value)}
                  style={{ padding: '12px', borderRadius: '12px', border: '1.5px solid #E2E8F0', fontFamily: 'inherit', fontSize: '0.95rem', outline: 'none' }}
                >
                  <option value="PUBLIC">📢 Public — ouvert à tous</option>
                  <option value="PRIVE">🔒 Privé — sur invitation</option>
                </select>
                <button
                  type="submit"
                  style={{
                    padding: '14px',
                    borderRadius: '14px',
                    background: 'linear-gradient(135deg, #1D4ED8, #3B82F6)',
                    color: 'white',
                    fontWeight: 800,
                    border: 'none',
                    cursor: 'pointer',
                    fontSize: '1rem',
                    boxShadow: '0 6px 18px rgba(29,78,216,0.3)',
                  }}
                >
                  Créer le groupe
                </button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <style>{`
        @keyframes pulse {
          0%, 100% { opacity: 1; transform: scale(1); }
          50% { opacity: 0.5; transform: scale(1.3); }
        }
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
      `}</style>
    </motion.div>
  </motion.div>
  );
};

export default Messaging;
